(() => {
'use strict';
const { CATEGORIES, updateNote, findNotes, encodeBackup, decodeNotes, planText, planBackup, loadSnapshot, saveSnapshot } = globalThis.Teum;

const $ = id => document.getElementById(id);
let storage;
let snapshot = { notes: [], raw: null };
let ready = false;
let editingId = null;
let deleted = null;
let pendingDeleteId = null;
let deleteTrigger = null;
const dateFormat = new Intl.DateTimeFormat('ko-KR', { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit', year: 'numeric' });
const newId = () => crypto.randomUUID();

function error(message) {
  $('storage-error').textContent = message;
  $('storage-error').hidden = !message;
}

function notice(message) {
  $('notice-text').textContent = message;
  $('notice').hidden = false;
  $('undo-delete').hidden = !deleted;
}

function persist(notes) {
  if (!ready) { error('저장소에 접근할 수 없어 저장하지 않았습니다. 작성 중인 내용은 복사해 보관해 주세요.'); return false; }
  try {
    snapshot = saveSnapshot(storage, notes, snapshot.raw);
    error('');
    render();
    return true;
  } catch (cause) {
    error(`저장하지 못했어요. 입력 내용과 기존 기록은 유지했습니다.\n${cause.message}`);
    return false;
  }
}

function render() {
  const notes = findNotes(snapshot.notes, $('search').value, $('filter').value);
  $('total-count').textContent = `${snapshot.notes.length}개 보관`;
  $('result-count').textContent = `${notes.length}개 표시 / 전체 ${snapshot.notes.length}개`;
  $('note-list').replaceChildren();
  $('empty-state').hidden = notes.length > 0;
  const hasFilter = $('search').value.trim() || $('filter').value !== 'all';
  $('empty-title').textContent = hasFilter ? '찾는 메모가 없어요' : '첫 메모를 남겨 보세요';
  $('empty-description').textContent = hasFilter ? '다른 단어를 쓰거나 분류를 바꿔 보세요.' : '지금 떠오른 한 문장부터 시작해요.';
  $('clear-filters').hidden = !hasFilter;
  if (!ready) {
    $('total-count').textContent = '확인 필요';
    $('result-count').textContent = '불러오기 실패';
    $('empty-title').textContent = '저장소를 확인해 주세요';
    $('empty-description').textContent = '기존 기록을 안전하게 읽지 못해 목록을 표시하지 않았어요.';
  }
  for (const note of notes) {
    const card = document.createElement('article');
    card.className = 'note-card';
    const meta = document.createElement('div');
    meta.className = 'note-meta';
    const category = document.createElement('span');
    category.className = 'category';
    category.dataset.category = note.category;
    category.textContent = CATEGORIES[note.category];
    category.hidden = note.category === 'other';
    const time = document.createElement('time');
    time.dateTime = note.updatedAt;
    time.textContent = `${dateFormat.format(new Date(note.updatedAt))}${note.createdAt !== note.updatedAt ? ' · 수정' : ''}`;
    meta.append(category, time);
    const body = document.createElement('p');
    body.className = 'note-body';
    body.textContent = note.body;
    const actions = document.createElement('div');
    actions.className = 'note-actions';
    for (const [label, action] of [['수정', 'edit'], ['삭제', 'delete']]) {
      const button = document.createElement('button');
      button.type = 'button';
      button.textContent = label;
      button.className = action;
      button.setAttribute('aria-label', `${note.body.slice(0, 28)} 메모 ${label}`);
      button.addEventListener('click', () => action === 'edit' ? edit(note) : askDelete(note, button));
      actions.append(button);
    }
    card.append(meta, body, actions);
    $('note-list').append(card);
  }
}

function isDraft() {
  const saved = snapshot.notes.find(note => note.id === editingId);
  if (saved) return $('note-body').value !== saved.body;
  return $('note-body').value.length > 0;
}

function edit(note) {
  if (isDraft() && !confirm('작성 중인 내용을 버리고 선택한 메모를 수정할까요?')) return;
  editingId = note.id;
  $('note-body').value = note.body;
  $('editor-title').textContent = '메모 다듬기';
  $('save-button').textContent = '수정 저장';
  $('cancel-edit').hidden = false;
  $('edit-badge').hidden = false;
  countCharacters();
  $('note-body').focus();
  $('capture').scrollIntoView({ block: 'nearest' });
}

function resetEditor() {
  editingId = null;
  $('note-form').reset();
  $('editor-title').textContent = '생각나는 대로 남겨요';
  $('save-button').textContent = '메모 남기기';
  $('cancel-edit').hidden = true;
  $('edit-badge').hidden = true;
  countCharacters();
}

function countCharacters() {
  const body = $('note-body').value;
  $('capture-help').textContent = editingId === null
    ? '한 줄에 메모 하나. 빈 줄은 건너뛰며, 각 줄은 2,000자까지 저장해요.'
    : '선택한 메모 한 개를 수정해요. 줄바꿈도 그대로 보존합니다. 최대 2,000자.';
  $('input-limit').textContent = editingId === null ? '한 번에 1,000,000자까지' : '줄바꿈 포함 2,000자까지';
  $('character-count').textContent = editingId === null
    ? `${body.split(/\r\n|\r|\n/).filter(line => line.trim()).length.toLocaleString('ko-KR')}개 메모 · ${body.length.toLocaleString('ko-KR')}자`
    : `${body.length.toLocaleString('ko-KR')} / 2,000`;
}

function askDelete(note, trigger) {
  pendingDeleteId = note.id;
  deleteTrigger = trigger;
  $('delete-preview').textContent = note.body;
  $('delete-dialog').returnValue = '';
  $('delete-dialog').showModal();
}

$('delete-dialog').addEventListener('close', () => {
  const id = pendingDeleteId;
  pendingDeleteId = null;
  if ($('delete-dialog').returnValue !== 'delete') { deleteTrigger?.focus(); return; }
  const note = snapshot.notes.find(item => item.id === id);
  if (!note || !persist(snapshot.notes.filter(item => item.id !== id))) { deleteTrigger?.focus(); return; }
  deleted = note;
  if (editingId === id) resetEditor();
  notice('메모를 삭제했어요. 마지막 삭제만 새로고침 전까지 되돌릴 수 있어요.');
  $('undo-delete').focus();
});

$('note-form').addEventListener('submit', event => {
  event.preventDefault();
  const wasEditing = editingId !== null;
  try {
    const now = new Date().toISOString();
    const previous = snapshot.notes.find(note => note.id === editingId);
    if (wasEditing && !previous) throw new Error('수정할 메모를 찾을 수 없어요. 내용을 복사해 새 메모로 남겨 주세요.');
    let notes;
    let added = 0;
    if (previous) {
      const note = updateNote(previous, $('note-body').value, previous.category, now);
      notes = snapshot.notes.map(item => item.id === editingId ? note : item);
    } else {
      const plan = planText(snapshot.notes, $('note-body').value, newId, now);
      notes = plan.notes;
      added = plan.added;
    }
    if (!persist(notes)) return;
    resetEditor();
    if (!wasEditing) { $('search').value = ''; $('filter').value = 'all'; render(); }
    notice(`${wasEditing ? '수정한 내용을' : `${added}개 메모를`} 저장했어요.${$('search').value.trim() || $('filter').value !== 'all' ? ' 검색 조건에 따라 목록에서 보이지 않을 수 있어요.' : ''}`);
    $('note-body').focus();
  } catch (cause) { error(cause.message); $('note-body').focus(); }
});

$('note-body').addEventListener('input', countCharacters);
$('note-body').addEventListener('keydown', event => {
  if ((event.ctrlKey || event.metaKey) && event.key === 'Enter' && !event.isComposing) { event.preventDefault(); $('note-form').requestSubmit(); }
});
$('cancel-edit').addEventListener('click', () => {
  if (!isDraft() || confirm('수정 중인 내용을 버릴까요? 저장된 메모는 그대로 남습니다.')) { resetEditor(); $('note-body').focus(); }
});
$('search').addEventListener('input', render);
$('filter').addEventListener('change', render);
$('clear-filters').addEventListener('click', () => { $('search').value = ''; $('filter').value = 'all'; render(); $('search').focus(); });
$('undo-delete').addEventListener('click', () => {
  if (!deleted) return;
  try {
    const plan = planBackup(snapshot.notes, [deleted], newId);
    if (plan.added && !persist(plan.notes)) return;
    deleted = null;
    notice(plan.conflicts ? '같은 식별자의 다른 기록이 있어 삭제한 메모를 사본으로 복원했어요.' : plan.added ? '삭제한 메모를 복원했어요.' : '이 메모는 이미 보관 중이에요.');
    $('search').focus();
  } catch (cause) { error(`삭제를 되돌리지 못했어요. 다시 시도할 수 있습니다.\n${cause.message}`); }
});

$('export').addEventListener('click', () => {
  try {
    // Read the persisted source again so another tab's latest records are included.
    const latest = loadSnapshot(storage);
    const now = new Date().toISOString();
    const url = URL.createObjectURL(new Blob([encodeBackup(latest.notes, now)], { type: 'application/json;charset=utf-8' }));
    const link = document.createElement('a');
    link.href = url;
    link.download = `teum-backup-${now.replace(/[:.]/g, '-')}.json`;
    document.body.append(link);
    try { link.click(); } finally { link.remove(); setTimeout(() => URL.revokeObjectURL(url), 1000); }
    notice(`저장된 ${latest.notes.length}개 메모의 백업 다운로드를 요청했어요. 다운로드 폴더에서 확인해 주세요. 작성 중인 내용은 포함되지 않습니다.`);
  } catch (cause) { error(`백업 파일을 만들지 못했어요. 기존 기록은 유지했습니다.\n${cause.message}`); }
});
$('import').addEventListener('click', () => $('import-file').click());
$('import-file').addEventListener('change', async event => {
  const file = event.target.files[0];
  event.target.value = '';
  if (!file) return;
  try {
    if (file.size > 25 * 1024 * 1024) throw new Error('25MB 이하의 백업 파일을 선택해 주세요.');
    const imported = decodeNotes(await file.text());
    if (!imported.length) { notice('백업 파일에 메모가 없어요. 기존 기록은 유지했습니다.'); return; }
    const plan = planBackup(snapshot.notes, imported, newId);
    if (!plan.added) { notice(`이미 보관된 ${plan.skipped}개 메모예요. 추가할 새 기록이 없습니다.`); return; }
    if (!confirm(`기존 ${snapshot.notes.length}개 메모를 유지하고 ${plan.added}개를 추가할까요?\n충돌 사본 ${plan.conflicts}개 · 중복 건너뛰기 ${plan.skipped}개\n기존 내용은 덮어쓰지 않습니다.`)) return;
    if (persist(plan.notes)) notice(`백업에서 ${plan.added}개를 가져왔어요. 충돌 사본 ${plan.conflicts}개, 중복 ${plan.skipped}개 건너뜀.${$('search').value.trim() || $('filter').value !== 'all' ? ' 검색 조건에 따라 목록에서 보이지 않을 수 있어요.' : ''}`);
  } catch (cause) { error(`백업을 가져오지 못했어요. 기존 기록은 유지했습니다.\n${cause.message}`); }
});

$('import-text').addEventListener('click', () => $('text-file').click());
$('text-file').addEventListener('change', async event => {
  const file = event.target.files[0];
  event.target.value = '';
  if (!file) return;
  try {
    if (file.size > 25 * 1024 * 1024) throw new Error('25MB 이하의 UTF-8 텍스트 파일을 선택해 주세요.');
    const plan = planText(snapshot.notes, await file.text(), newId, new Date().toISOString());
    if (!confirm(`일반 글에서 ${plan.added}개 메모를 추가할까요?\n비어 있지 않은 각 줄을 메모로 저장합니다. 기존 기록과 작성 중인 내용은 유지해요.\n같은 글을 다시 가져오면 별도 메모로 추가됩니다.`)) return;
    if (persist(plan.notes)) {
      $('search').value = ''; $('filter').value = 'all'; render();
      notice(`일반 글에서 ${plan.added}개 메모를 추가했어요. 작성 중인 내용은 유지했습니다.`);
    }
  } catch (cause) { error(`글 파일을 가져오지 못했어요. 기존 기록과 작성 중인 내용은 유지했습니다.\n${cause.message}`); }
});

window.addEventListener('beforeunload', event => {
  if (!isDraft()) return;
  event.preventDefault();
  event.returnValue = '';
});

try {
  storage = window.localStorage;
  snapshot = loadSnapshot(storage);
  ready = true;
} catch (cause) {
  error(`기존 저장소를 읽지 못해 변경을 잠갔어요. 저장소를 비우지 말고 브라우저 설정과 README의 복구 안내를 확인해 주세요.\n${cause.message}`);
}
for (const id of ['save-button', 'import', 'import-text', 'export']) $(id).disabled = !ready;
countCharacters();
render();
})();

