(() => {
'use strict';
const STORAGE_KEY = 'teum.notes.v1';
const CATEGORIES = Object.freeze({ idea: '아이디어', todo: '할 일', observation: '관찰', other: '기타' });
const MAX_BODY = 2000;
const MAX_NOTES = 10000;
const MAX_TEXT = 1000000;
const BACKUP_FORMAT = 'teum-notes';

function content(body, category) {
  if (typeof body !== 'string' || !body.trim()) throw new Error('메모 내용을 입력해 주세요.');
  if (body.length > MAX_BODY) throw new Error('메모는 2,000자까지 남길 수 있어요.');
  if (typeof category !== 'string' || !Object.hasOwn(CATEGORIES, category)) throw new Error('올바른 분류를 선택해 주세요.');
  return { body: body.trim(), category };
}

function createNote(body, category, id, now) {
  const note = { id, ...content(body, category), createdAt: now, updatedAt: now };
  validateNotes([note]);
  return note;
}

function updateNote(note, body, category, now) {
  const updated = { ...note, ...content(body, category), updatedAt: now };
  validateNotes([updated]);
  return updated;
}

function validateNotes(notes) {
  if (!Array.isArray(notes) || notes.length > MAX_NOTES) throw new Error('메모 목록 형식이나 개수를 확인해 주세요.');
  const ids = new Set();
  for (const note of notes) {
    if (!note || typeof note !== 'object' || typeof note.id !== 'string' || !/^[a-zA-Z0-9_-]{1,128}$/.test(note.id) || ids.has(note.id)) throw new Error('메모 식별자가 올바르지 않거나 중복됩니다.');
    content(note.body, note.category);
    for (const field of ['createdAt', 'updatedAt']) {
      if (typeof note[field] !== 'string' || !Number.isFinite(Date.parse(note[field])) || new Date(note[field]).toISOString() !== note[field]) throw new Error('메모 날짜 형식이 올바르지 않습니다.');
    }
    ids.add(note.id);
  }
  return notes.map(({ id, body, category, createdAt, updatedAt }) => ({ id, body, category, createdAt, updatedAt }));
}

function encodeNotes(notes) {
  return JSON.stringify({ version: 1, notes: validateNotes(notes) });
}

function encodeBackup(notes, exportedAt) {
  return JSON.stringify({ format: BACKUP_FORMAT, version: 1, exportedAt, notes: validateNotes(notes) }, null, 2);
}

function decodeNotes(raw) {
  if (raw === null) return [];
  let data;
  try { data = JSON.parse(typeof raw === 'string' ? raw.replace(/^\uFEFF/, '') : raw); } catch { throw new Error('저장 파일을 읽을 수 없습니다. JSON 형식을 확인해 주세요.'); }
  if (!data || data.version !== 1) throw new Error('지원하지 않는 백업 버전입니다.');
  if (data.format !== undefined && data.format !== BACKUP_FORMAT) throw new Error('틈 메모 백업 파일이 아닙니다.');
  return validateNotes(data.notes);
}

function findNotes(notes, query = '', category = 'all') {
  const terms = query.normalize('NFC').trim().toLocaleLowerCase('ko').split(/\s+/).filter(Boolean);
  return notes.filter(note => (category === 'all' || note.category === category) && terms.every(term => note.body.normalize('NFC').toLocaleLowerCase('ko').includes(term)))
    .sort((a, b) => b.updatedAt.localeCompare(a.updatedAt) || b.createdAt.localeCompare(a.createdAt));
}

// A new capture is one record per non-empty line. Editing never calls this parser.
function planText(current, text, newId, now) {
  const existing = validateNotes(current);
  if (typeof text !== 'string' || !text.trim()) throw new Error('메모 내용을 입력해 주세요.');
  if (text.length > MAX_TEXT) throw new Error('한 번에 1,000,000자까지 입력할 수 있어요. 글을 나눠 저장해 주세요.');
  if (text.includes('\u0000')) throw new Error('일반 UTF-8 텍스트를 입력해 주세요.');
  const bodies = [];
  for (const [index, line] of text.replace(/^\uFEFF/, '').split(/\r\n|\r|\n/).entries()) {
    if (!line.trim()) continue;
    if (line.length > MAX_BODY) throw new Error(`${index + 1}번째 줄이 2,000자를 넘어요. 줄을 나눈 뒤 다시 저장해 주세요. 아무 메모도 추가하지 않았습니다.`);
    bodies.push(line);
  }
  if (!bodies.length) throw new Error('메모 내용을 입력해 주세요.');
  if (existing.length + bodies.length > MAX_NOTES) throw new Error('최대 10,000개 메모를 보관할 수 있어요. 아무 메모도 추가하지 않았습니다.');
  const incoming = bodies.map(body => createNote(body, 'other', newId(), now));
  return { notes: validateNotes([...existing, ...incoming]), added: incoming.length };
}

// Same IDs with different content are preserved as separate copies; nothing is overwritten.
function planBackup(current, incoming, newId) {
  const merged = validateNotes(current);
  const startingCount = merged.length;
  let conflicts = 0;
  let skipped = 0;
  const byId = new Map(merged.map(note => [note.id, note]));
  const fingerprint = ({ body, category, createdAt, updatedAt }) => JSON.stringify({ body, category, createdAt, updatedAt });
  const fingerprints = new Set(merged.map(fingerprint));
  for (const candidate of validateNotes(incoming)) {
    if (byId.has(candidate.id) && fingerprints.has(fingerprint(candidate))) { skipped++; continue; }
    const collision = byId.has(candidate.id);
    const copy = collision ? { ...candidate, id: newId() } : candidate;
    if (collision) conflicts++;
    merged.push(copy);
    byId.set(copy.id, copy);
    fingerprints.add(fingerprint(copy));
  }
  return { notes: validateNotes(merged), added: merged.length - startingCount, conflicts, skipped };
}

function mergeBackup(current, incoming, newId) { return planBackup(current, incoming, newId).notes; }

function loadSnapshot(storage) {
  const raw = storage.getItem(STORAGE_KEY);
  return { raw, notes: decodeNotes(raw) };
}

function saveSnapshot(storage, notes, expectedRaw) {
  if (storage.getItem(STORAGE_KEY) !== expectedRaw) throw new Error('다른 창에서 기록이 바뀌었어요. 작성 중인 내용을 복사한 뒤 새로고침해 주세요. 기존 기록을 덮어쓰지 않았습니다.');
  const raw = encodeNotes(notes);
  storage.setItem(STORAGE_KEY, raw);
  return { raw, notes: validateNotes(notes) };
}

globalThis.Teum = Object.freeze({ STORAGE_KEY, CATEGORIES, MAX_BODY, MAX_NOTES, MAX_TEXT, BACKUP_FORMAT, createNote, updateNote, validateNotes, encodeNotes, encodeBackup, decodeNotes, findNotes, planText, planBackup, mergeBackup, loadSnapshot, saveSnapshot });
})();

