import test from 'node:test';
import assert from 'node:assert/strict';
import '../model.js';

const { STORAGE_KEY, MAX_TEXT, MAX_NOTES, createNote, updateNote, findNotes, encodeNotes, encodeBackup, decodeNotes, planText, planBackup, mergeBackup, loadSnapshot, saveSnapshot } = globalThis.Teum;
const first = '2026-10-17T09:00:00.000Z';
const later = '2026-10-17T10:00:00.000Z';
const note = (body = '가상 현장 메모', category = 'idea', id = 'note-1', now = first) => createNote(body, category, id, now);
function memoryStorage(initial = null) {
  let raw = initial;
  return { getItem(key) { assert.equal(key, STORAGE_KEY); return raw; }, setItem(key, value) { assert.equal(key, STORAGE_KEY); raw = value; } };
}

test('입력과 수정은 공백을 다듬고 식별자·생성일을 보존한다', () => {
  const original = note('  가상 아이디어  ');
  const revised = updateNote(original, '  가상 수정\n두 번째 줄 ', 'todo', later);
  assert.equal(original.body, '가상 아이디어');
  assert.deepEqual(revised, { id: original.id, body: '가상 수정\n두 번째 줄', category: 'todo', createdAt: first, updatedAt: later });
  assert.equal(original.category, 'idea');
});

test('빈 입력, 긴 입력, 알 수 없는 분류를 거부한다', () => {
  for (const text of ['', ' \n\t', '가'.repeat(2001)]) assert.throws(() => note(text));
  assert.throws(() => note('가상 메모', 'constructor'));
  assert.equal(note('가'.repeat(2000)).body.length, 2000);
});

test('여러 검색어 AND, 대소문자, 한글 정규화, 분류를 함께 적용한다', () => {
  const notes = [note('가상 현장 UI 스케치'), note('가상 현장 연락하기', 'todo', 'note-2')];
  assert.deepEqual(findNotes(notes, '현장 ui', 'idea').map(item => item.id), ['note-1']);
  assert.equal(findNotes(notes, '없는단어').length, 0);
  assert.equal(findNotes(notes, '현장'.normalize('NFD')).length, 2);
  assert.equal(findNotes(notes, '', 'todo').length, 1);
});

test('검색 목록은 최근 수정 순이며 원본 배열 순서는 유지한다', () => {
  const notes = [note(), note('가상 두 번째', 'other', 'note-2', later)];
  assert.deepEqual(findNotes(notes).map(item => item.id), ['note-2', 'note-1']);
  assert.equal(notes[0].id, 'note-1');
});

test('추가·수정·삭제·복원 후 새 저장소 읽기로 보존을 검증한다', () => {
  const storage = memoryStorage();
  let state = loadSnapshot(storage);
  assert.deepEqual(state.notes, []);
  state = saveSnapshot(storage, [note()], state.raw);
  state = loadSnapshot(storage);
  assert.equal(state.notes[0].body, '가상 현장 메모');
  const revised = updateNote(state.notes[0], '가상 수정', 'observation', later);
  state = saveSnapshot(storage, [revised], state.raw);
  assert.equal(loadSnapshot(storage).notes[0].body, '가상 수정');
  state = saveSnapshot(storage, [], state.raw);
  assert.deepEqual(loadSnapshot(storage).notes, []);
  saveSnapshot(storage, [revised], state.raw);
  assert.deepEqual(loadSnapshot(storage).notes, [revised]);
});

test('용량 초과와 저장소 접근 오류가 호출자에게 전달되고 기존 데이터는 유지된다', () => {
  const raw = encodeNotes([note()]);
  const storage = { getItem() { return raw; }, setItem() { throw new Error('QuotaExceededError'); } };
  assert.throws(() => saveSnapshot(storage, [], raw), /QuotaExceededError/);
  assert.equal(storage.getItem(), raw);
  assert.throws(() => loadSnapshot({ getItem() { throw new Error('SecurityError'); } }), /SecurityError/);
});

test('다른 창에서 갱신된 데이터는 오래된 화면이 덮어쓰지 않는다', () => {
  const storage = memoryStorage();
  const firstTab = loadSnapshot(storage);
  const secondTab = loadSnapshot(storage);
  saveSnapshot(storage, [note()], firstTab.raw);
  assert.throws(() => saveSnapshot(storage, [], secondTab.raw), /다른 창/);
  assert.equal(loadSnapshot(storage).notes.length, 1);
});

test('손상, 미지원 버전, 중복 식별자와 잘못된 날짜를 거부한다', () => {
  const bad = ['{', 'null', '{}', JSON.stringify({ version: 2, notes: [] }), JSON.stringify({ version: 1, notes: [note(), note()] }), JSON.stringify({ version: 1, notes: [{ ...note(), updatedAt: '어제' }] })];
  for (const raw of bad) assert.throws(() => decodeNotes(raw));
});

test('분류는 문자열만 허용하고 배열의 암묵적 키 변환을 거부한다', () => {
  for (const category of [['idea'], ['todo'], {}, null, 0, true]) {
    assert.throws(() => note('가상 입력', category));
    assert.throws(() => decodeNotes(JSON.stringify({ version: 1, notes: [{ ...note(), category }] })));
  }
});

test('백업은 왕복 보존하고 같은 메모를 반복 가져와도 늘어나지 않는다', () => {
  const current = [note()];
  const incoming = decodeNotes(encodeNotes(current));
  assert.deepEqual(incoming, current);
  assert.deepEqual(mergeBackup(current, incoming, () => 'copy'), current);
});

test('서로 다른 ID로 의도적으로 만든 동일한 내용의 기록도 모두 보존한다', () => {
  const current = [note()];
  const incoming = [note('가상 현장 메모', 'idea', 'note-2')];
  assert.equal(mergeBackup(current, incoming, () => 'copy').length, 2);
});

test('같은 ID의 다른 내용을 가져오면 사본으로 보존하고 재가져오기는 중복시키지 않는다', () => {
  const current = [note()];
  const incoming = [updateNote(current[0], '가상 다른 기기의 수정', 'todo', later)];
  const merged = mergeBackup(current, incoming, () => 'copy');
  assert.equal(merged.length, 2);
  assert.equal(merged[0].body, current[0].body);
  assert.equal(merged[1].id, 'copy');
  assert.deepEqual(mergeBackup(merged, incoming, () => 'copy-2'), merged);
});

test('백업에 들어 있는 HTML은 문자열 그대로 왕복하며 실행 코드로 처리하지 않는다', () => {
  const original = note('<img src=x onerror="alert(1)">');
  assert.equal(decodeNotes(encodeNotes([original]))[0].body, original.body);
});

test('식별 가능한 파일 형식과 이전 파일 형식, UTF-8 BOM을 읽는다', () => {
  const notes = [note('가상 한글 🌿\n여러 줄')];
  const exported = encodeBackup(notes, later);
  assert.deepEqual(JSON.parse(exported), { format: 'teum-notes', version: 1, exportedAt: later, notes });
  assert.deepEqual(decodeNotes(exported), notes);
  assert.deepEqual(decodeNotes('\uFEFF' + exported), notes);
  assert.deepEqual(decodeNotes(encodeNotes(notes)), notes);
  assert.throws(() => decodeNotes(JSON.stringify({ format: 'other', version: 1, notes })), /백업 파일이 아닙니다/);
});

test('가져오기 계획은 추가·충돌·중복 수를 제공하고 입력 배열을 바꾸지 않는다', () => {
  const current = [note(), note('가상 두 번째', 'todo', 'note-2')];
  const incoming = [{ ...current[0], body: '가상 충돌' }, current[1], note('가상 새 기록', 'other', 'note-3')];
  const before = JSON.stringify(current);
  const plan = planBackup(current, incoming, () => 'copy');
  assert.equal(plan.added, 2);
  assert.equal(plan.conflicts, 1);
  assert.equal(plan.skipped, 1);
  assert.equal(plan.notes.length, 4);
  assert.equal(JSON.stringify(current), before);
});

test('일반 글은 빈 줄을 건너뛰고 각 줄을 순서대로 별도 메모로 만든다', () => {
  const current = [note('가상 기존\n여러 줄', 'idea')];
  const before = JSON.stringify(current);
  let id = 0;
  const plan = planText(current, '\uFEFF 가상 첫 줄 \r\n \t\r\n가상 🌿 둘째\r가상 첫 줄\n', () => `new-${++id}`, later);
  assert.equal(plan.added, 3);
  assert.equal(JSON.stringify(current), before);
  assert.deepEqual(plan.notes[0], current[0]);
  assert.deepEqual(plan.notes.slice(1).map(item => item.body), ['가상 첫 줄', '가상 🌿 둘째', '가상 첫 줄']);
  assert.ok(plan.notes.slice(1).every(item => item.category === 'other' && item.createdAt === later));
  assert.deepEqual(findNotes(plan.notes).slice(0, 3).map(item => item.id), ['new-1', 'new-2', 'new-3']);
  assert.deepEqual(decodeNotes(encodeBackup(plan.notes, later)), plan.notes);
});

test('일반 글의 빈 입력·전체 길이·줄 길이·최대 메모 수를 전체 저장 전에 검증한다', () => {
  const current = [note()];
  const before = JSON.stringify(current);
  for (const text of [null, '', ' \n\r\t', '\u0000', '가'.repeat(MAX_TEXT + 1), '가상 첫 줄\n' + '가'.repeat(2001)]) {
    assert.throws(() => planText(current, text, () => 'new-id', later));
    assert.equal(JSON.stringify(current), before);
  }
  let id = 0;
  const full = Array.from({ length: MAX_NOTES }, (_, index) => note('가상 기존', 'other', `old-${index}`));
  assert.throws(() => planText(full, '가상 추가', () => `new-${++id}`, later), /10,000/);
  assert.equal(id, 0);
  assert.equal(full.length, MAX_NOTES);
  const bounded = planText([], '가'.repeat(2000) + '\n' + '나'.repeat(2000), () => `new-${++id}`, later);
  assert.equal(bounded.added, 2);
});

