import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import vm from 'node:vm';
import { webcrypto } from 'node:crypto';

// A small DOM stand-in for event/storage integration. This is not browser rendering.
const html = readFileSync(new URL('../index.html', import.meta.url), 'utf8');
const modelSource = readFileSync(new URL('../model.js', import.meta.url), 'utf8');
const appSource = readFileSync(new URL('../app.js', import.meta.url), 'utf8');

function boot(initialRaw = null) {
  const ids = [...html.matchAll(/id="([^"]+)"/g)].map(match => match[1]);
  const elements = new Map();
  let focused = null;
  let confirmation = true;
  const windowListeners = new Map();
  const downloads = [];
  const confirmations = [];
  const blobs = new Map();
  const urlApi = { createObjectURL(blob) { const url = `blob:test-${blobs.size}`; blobs.set(url, blob); return url; }, revokeObjectURL(url) { blobs.delete(url); } };
  class Element {
    constructor(id = '') { this.id = id; this.value = ''; this.textContent = ''; this.hidden = false; this.dataset = {}; this.children = []; this.listeners = new Map(); this.attributes = {}; }
    addEventListener(name, callback) { this.listeners.set(name, callback); }
    fire(name, extra = {}) { return this.listeners.get(name)?.({ preventDefault() {}, target: this, ...extra }); }
    append(...children) { this.children.push(...children); }
    replaceChildren() { this.children = []; }
    setAttribute(name, value) { this.attributes[name] = value; }
    focus() { focused = this; }
    scrollIntoView() {}
    showModal() { this.open = true; }
    click() { if (this.download) downloads.push({ name: this.download, blob: blobs.get(this.href) }); else this.fire('click'); }
    remove() {}
    reset() { elements.get('note-body').value = ''; }
    requestSubmit() { this.fire('submit'); }
  }
  for (const id of ids) elements.set(id, new Element(id));
  elements.get('filter').value = 'all';
  let raw = initialRaw;
  let failWrites = false;
  const storage = { getItem() { return raw; }, setItem(key, value) { if (failWrites) throw new Error('QuotaExceededError'); raw = value; } };
  const context = vm.createContext({ document: { body: new Element('body'), getElementById(id) { assert.ok(elements.has(id), `Missing element: ${id}`); return elements.get(id); }, createElement() { return new Element(); } }, window: { localStorage: storage, addEventListener(name, callback) { windowListeners.set(name, callback); } }, crypto: webcrypto, confirm: message => { confirmations.push(message); return confirmation; }, Intl, Date, Blob, URL: urlApi, setTimeout: callback => callback() });
  vm.runInContext(modelSource, context);
  vm.runInContext(appSource, context);
  return { get: id => elements.get(id), get raw() { return raw; }, get focused() { return focused; }, downloads, confirmations, set failWrites(value) { failWrites = value; }, set confirmation(value) { confirmation = value; }, externalWrite(value) { raw = value; }, fireWindow(name, event) { windowListeners.get(name)?.(event); } };
}

function save(app, body) {
  app.get('note-body').value = body;
  app.get('note-form').fire('submit');
}

async function importFile(app, raw, options = {}) {
  app.get('import-file').files = [{ size: Buffer.byteLength(raw), text: async () => raw, ...options }];
  await app.get('import-file').fire('change');
}

test('입력 → 저장 → 앱 재시작 → 검색 → 수정 → 삭제 → 되돌리기 이벤트 연결', () => {
  let app = boot();
  save(app, '가상 선반 스케치');
  assert.equal(app.get('note-body').value, '');
  assert.equal(app.get('note-list').children.length, 1);
  app = boot(app.raw);
  assert.equal(app.get('note-list').children[0].children[1].textContent, '가상 선반 스케치');
  app.get('search').value = '없음';
  app.get('search').fire('input');
  assert.equal(app.get('note-list').children.length, 0);
  app.get('clear-filters').fire('click');
  let card = app.get('note-list').children[0];
  card.children[2].children[0].fire('click');
  save(app, '가상 수정한 스케치');
  card = app.get('note-list').children[0];
  assert.equal(card.children[1].textContent, '가상 수정한 스케치');
  card.children[2].children[1].fire('click');
  assert.equal(app.get('delete-dialog').open, true);
  app.get('delete-dialog').returnValue = 'delete';
  app.get('delete-dialog').fire('close');
  assert.equal(JSON.parse(app.raw).notes.length, 0);
  assert.equal(app.focused.id, 'undo-delete');
  app.get('undo-delete').fire('click');
  assert.equal(JSON.parse(app.raw).notes[0].body, '가상 수정한 스케치');
});

test('저장 실패는 입력, 목록과 기존 저장 원문을 보존한다', () => {
  const app = boot();
  save(app, '가상 기존 기록');
  const raw = app.raw;
  app.failWrites = true;
  save(app, '가상 아직 저장되지 않은 입력');
  assert.equal(app.raw, raw);
  assert.equal(app.get('note-body').value, '가상 아직 저장되지 않은 입력');
  assert.equal(app.get('note-list').children.length, 1);
  assert.match(app.get('storage-error').textContent, /저장하지 못했어요/);
});

test('손상 원문은 보존하고 저장·가져오기·내보내기를 잠근다', () => {
  const app = boot('{broken');
  assert.equal(app.raw, '{broken');
  for (const id of ['save-button', 'import', 'import-text', 'export']) assert.equal(app.get(id).disabled, true);
  assert.equal(app.get('result-count').textContent, '불러오기 실패');
});

test('삭제 취소는 기록과 원문을 바꾸지 않는다', () => {
