test('새 메모와 수정의 빈 입력을 거부하고 원본을 보존한 채 다시 저장할 수 있다', () => {
  const app = boot();
  save(app, '가상 저장 원본');
  const raw = app.raw;
  for (const body of ['', ' \n\t']) {
    save(app, body);
    assert.equal(app.raw, raw);
    assert.equal(app.get('note-body').value, body);
    assert.match(app.get('storage-error').textContent, /내용을 입력/);
  }
  app.get('note-body').value = '';
  app.get('note-list').children[0].children[2].children[0].fire('click');
  save(app, ' \n');
  assert.equal(app.raw, raw);
  assert.equal(app.get('save-button').textContent, '수정 저장');
  save(app, '가상 다시 쓴 내용');
  const records = JSON.parse(app.raw).notes;
  assert.equal(records.length, 1);
  assert.equal(records[0].id, JSON.parse(raw).notes[0].id);
  assert.equal(records[0].body, '가상 다시 쓴 내용');
});

test('수정 취소는 원본을 보존하고 이후 새 입력은 별도 기록으로 저장한다', () => {
