test('내용을 모두 지운 편집도 저장되지 않은 변경으로 떠나기 경고를 요청한다', () => {
  const app = boot();
  save(app, '가상 원본');
  app.get('note-list').children[0].children[2].children[0].fire('click');
  app.get('note-body').value = '';
  let prevented = false;
  app.fireWindow('beforeunload', { preventDefault() { prevented = true; } });
  assert.equal(prevented, true);
  assert.equal(JSON.parse(app.raw).notes[0].body, '가상 원본');
});

test('변경 없는 편집에는 떠나기 경고가 없고 본문을 수정하면 경고를 요청한다', () => {
  const app = boot();
  save(app, '가상 원본');
  app.get('note-list').children[0].children[2].children[0].fire('click');
  let prevented = false;
  app.fireWindow('beforeunload', { preventDefault() { prevented = true; } });
  assert.equal(prevented, false);
  app.get('note-body').value += ' 수정';
  app.fireWindow('beforeunload', { preventDefault() { prevented = true; } });
  assert.equal(prevented, true);
  assert.equal(JSON.parse(app.raw).notes[0].category, 'other');
});

