test('잘못된 필드가 섞인 저장 데이터는 한 건도 덮어쓰지 않고 잠근다', () => {
  const fixture = boot();
  save(fixture, '가상 정상 기록');
  const valid = JSON.parse(fixture.raw).notes[0];
  const badValues = [null, [], { ...valid, id: 'bad-category', category: ['idea'] }, { ...valid, id: 'bad-body', body: ' \n' }, { ...valid, id: 'bad-date', updatedAt: 'yesterday' }];
  for (const bad of badValues) {
    const raw = JSON.stringify({ version: 1, notes: [valid, bad] });
    const app = boot(raw);
    assert.equal(app.get('save-button').disabled, true);
    assert.equal(app.get('result-count').textContent, '불러오기 실패');
    save(app, '가상 덮어쓰기 시도');
    assert.equal(app.raw, raw);
  }
});

test('전체 저장 기록을 UTF-8 JSON으로 내보내 별도 저장 공간에 추가하고 재시작한다', async () => {
  const source = boot(legacyRaw());
  save(source, '가상 다른 기록');
  source.get('search').value = '한글';
  source.get('search').fire('input');
  source.get('note-body').value = '가상 미저장 초안';
  source.get('export').fire('click');
  assert.equal(source.downloads.length, 1);
  assert.match(source.downloads[0].name, /^teum-backup-.*\.json$/);
  const raw = await source.downloads[0].blob.text();
  const backup = JSON.parse(raw);
  assert.equal(backup.format, 'teum-notes');
  assert.equal(backup.version, 1);
  assert.ok(Number.isFinite(Date.parse(backup.exportedAt)));
  assert.deepEqual(backup.notes, JSON.parse(source.raw).notes);
  const target = boot();
  save(target, '가상 대상 브라우저 기존 기록');
  const original = JSON.parse(target.raw).notes[0];
  target.get('note-body').value = '가상 대상 초안';
  await importFile(target, raw);
  assert.equal(target.get('note-body').value, '가상 대상 초안');
  assert.deepEqual(JSON.parse(target.raw).notes, [original, ...backup.notes]);
  assert.equal(boot(target.raw).get('note-list').children.length, 3);
  const firstImport = target.raw;
  await importFile(target, raw);
  assert.equal(target.raw, firstImport);
});

test('파일 가져오기 취소·손상·버전 불일치·다른 형식·크기 초과·읽기 실패는 원문을 유지한다', async () => {
  const app = boot();
  save(app, '가상 기존 기록');
  const raw = app.raw;
  const incoming = JSON.stringify({ version: 1, notes: [{ ...JSON.parse(raw).notes[0], id: 'incoming', body: '가상 가져올 기록' }] });
  app.confirmation = false;
  await importFile(app, incoming);
  assert.equal(app.raw, raw);
  app.confirmation = true;
  for (const bad of ['{', JSON.stringify({ version: 8, notes: [] }), JSON.stringify({ format: 'another-app', version: 1, notes: [] }), JSON.stringify({ version: 1, notes: [{ ...JSON.parse(raw).notes[0], body: '' }] })]) {
    await importFile(app, bad);
    assert.equal(app.raw, raw);
    assert.match(app.get('storage-error').textContent, /가져오지 못했어요/);
  }
  await importFile(app, incoming, { size: 25 * 1024 * 1024 + 1 });
  assert.equal(app.raw, raw);
  await importFile(app, incoming, { text: async () => { throw new Error('가상 파일 읽기 실패'); } });
  assert.equal(app.raw, raw);
  assert.match(app.get('storage-error').textContent, /파일 읽기 실패/);
});

test('충돌 사본과 중복 수를 확인하고 원본 보존 후 반복 가져오기에서 늘어나지 않는다', async () => {
  const app = boot();
  save(app, '가상 현재 기록');
  save(app, '가상 동일 기록');
  const before = JSON.parse(app.raw).notes;
  const incoming = JSON.stringify({ version: 1, notes: [{ ...before[0], body: '가상 다른 브라우저 수정' }, before[1]] });
  await importFile(app, incoming);
  assert.match(app.confirmations.at(-1), /충돌 사본 1개 · 중복 건너뛰기 1개/);
  const after = JSON.parse(app.raw).notes;
  assert.deepEqual(after.slice(0, 2), before);
  assert.equal(after[2].body, '가상 다른 브라우저 수정');
  assert.notEqual(after[2].id, before[0].id);
  const raw = app.raw;
  await importFile(app, incoming);
  assert.equal(app.raw, raw);
});

