test('삭제 뒤 같은 ID의 다른 백업을 가져와도 삭제 원본을 사본으로 되돌린다', async () => {
  const app = boot();
  save(app, '가상 삭제 원본');
  const original = JSON.parse(app.raw).notes[0];
  app.get('note-list').children[0].children[2].children[1].fire('click');
  app.get('delete-dialog').returnValue = 'delete';
  app.get('delete-dialog').fire('close');
  await importFile(app, JSON.stringify({ version: 1, notes: [{ ...original, body: '가상 다른 브라우저 기록' }] }));
  app.get('undo-delete').fire('click');
  const after = JSON.parse(app.raw).notes;
  assert.equal(after.length, 2);
  assert.deepEqual(after.map(note => note.body), ['가상 다른 브라우저 기록', '가상 삭제 원본']);
  assert.notEqual(after[0].id, after[1].id);
});

function legacyRaw() {
  return JSON.stringify({ version: 1, notes: [{ id: 'legacy-1', body: '가상 한글 기록 🌿\n두 번째 줄', category: 'idea', createdAt: '2026-10-17T09:00:00.000Z', updatedAt: '2026-10-17T09:00:00.000Z' }] });
}

async function importText(app, body, options = {}) {
  app.get('text-file').files = [{ name: '현장.txt', size: Buffer.byteLength(body), text: async () => body, ...options }];
  await app.get('text-file').fire('change');
}

test('분류 선택 없이 여러 줄을 한 번 저장하고 내용으로 찾아 선택한 한 건만 수정한다', () => {
  assert.doesNotMatch(html, /id="note-category"|maxlength="2000"/);
  let app = boot(legacyRaw());
  const legacy = JSON.parse(app.raw).notes[0];
  const body = '가상 문틀 치수 확인\r\n\r\n가상 작업등 가져오기 🌿\r가상 <b>유리창</b>\n가상 문틀 치수 확인';
  app.get('note-body').value = body;
  app.get('note-body').fire('input');
  assert.match(app.get('character-count').textContent, /4개 메모/);
  app.get('note-form').fire('submit');
  assert.equal(app.confirmations.length, 0);
  const before = JSON.parse(app.raw).notes;
  assert.equal(before.length, 5);
  assert.deepEqual(before[0], legacy);
  assert.deepEqual(before.slice(1).map(note => note.body), ['가상 문틀 치수 확인', '가상 작업등 가져오기 🌿', '가상 <b>유리창</b>', '가상 문틀 치수 확인']);
  assert.ok(before.slice(1).every(note => note.category === 'other'));
  assert.equal(new Set(before.map(note => note.id)).size, 5);
  app = boot(app.raw);
  app.get('search').value = '작업등 🌿';
  app.get('search').fire('input');
  assert.equal(app.get('note-list').children.length, 1);
  app.get('note-list').children[0].children[2].children[0].fire('click');
  save(app, '가상 작업등 준비 완료 🌿\n추가 설명');
  const after = JSON.parse(app.raw).notes;
  assert.equal(after.length, 5);
  assert.equal(after[2].body, '가상 작업등 준비 완료 🌿\n추가 설명');
  assert.equal(after[2].id, before[2].id);
  assert.deepEqual(after.filter((_, index) => index !== 2), before.filter((_, index) => index !== 2));
});

test('기존 여러 줄 메모는 나누지 않고 수정하며 분류·생성일·식별자를 보존한다', () => {
