test('긴 붙여넣기도 줄별 한도 안이면 저장하고 실패한 묶음은 통째로 보존한다', () => {
  const app = boot();
  const accepted = '가'.repeat(1500) + '\n' + '나'.repeat(1500);
  save(app, accepted);
  assert.equal(JSON.parse(app.raw).notes.length, 2);
  const raw = app.raw;
  const rejected = '가상 짧은 줄\n' + '다'.repeat(2001);
  save(app, rejected);
  assert.equal(app.raw, raw);
  assert.equal(app.get('note-body').value, rejected);
  assert.match(app.get('storage-error').textContent, /2번째 줄/);
  app.failWrites = true;
  save(app, '가상 첫 줄\n가상 둘째 줄');
  assert.equal(app.raw, raw);
  assert.equal(app.get('note-body').value, '가상 첫 줄\n가상 둘째 줄');
});

test('일반 Enter와 한글 조합은 저장하지 않으며 Ctrl/⌘ Enter는 묶음을 저장한다', () => {
  for (const modifier of ['ctrlKey', 'metaKey']) {
    const app = boot();
    app.get('note-body').value = '가상 첫 줄\n가상 다음 줄';
    app.get('note-body').fire('keydown', { key: 'Enter' });
    app.get('note-body').fire('keydown', { key: 'Enter', [modifier]: true, isComposing: true });
    assert.equal(app.raw, null);
    app.get('note-body').fire('keydown', { key: 'Enter', [modifier]: true, isComposing: false });
    assert.equal(JSON.parse(app.raw).notes.length, 2);
  }
});

test('UTF-8 일반 글 파일은 전용 형식 없이 가져오고 초안·기존 기록·백업 이동을 보존한다', async () => {
  const app = boot(legacyRaw());
