test('일반 글 파일 취소·빈 글·긴 줄·크기·읽기·저장 실패는 기존 원문과 초안을 보존한다', async () => {
  const app = boot(legacyRaw());
  const raw = app.raw;
  app.get('note-body').value = '가상 유지할 초안';
  app.confirmation = false;
  await importText(app, '가상 파일 첫 줄\n둘째 줄');
  assert.equal(app.raw, raw);
  app.confirmation = true;
  for (const body of ['', ' \n\t', '가상 정상\n' + '가'.repeat(2001), '가상\u0000본문']) {
    await importText(app, body);
    assert.equal(app.raw, raw);
    assert.match(app.get('storage-error').textContent, /글 파일을 가져오지 못했어요/);
  }
  await importText(app, '가상 글', { size: 25 * 1024 * 1024 + 1 });
  assert.equal(app.raw, raw);
  await importText(app, '가상 글', { text: async () => { throw new Error('읽기 실패'); } });
  assert.equal(app.raw, raw);
  app.failWrites = true;
  await importText(app, '가상 파일 첫 줄\n둘째 줄');
  assert.equal(app.raw, raw);
  assert.equal(app.get('note-body').value, '가상 유지할 초안');
});

test('다른 창의 변경이 있으면 붙여넣기 묶음과 글 파일 모두 덮어쓰지 않는다', async () => {
  const app = boot(legacyRaw());
  const other = JSON.parse(app.raw);
  other.notes[0].body = '가상 다른 창 변경';
  const raw = JSON.stringify(other);
  app.externalWrite(raw);
  save(app, '가상 첫 줄\n둘째 줄');
  assert.equal(app.raw, raw);
  await importText(app, '가상 파일 첫 줄\n둘째 줄');
  assert.equal(app.raw, raw);
  assert.equal(app.get('note-body').value, '가상 첫 줄\n둘째 줄');
  assert.match(app.get('storage-error').textContent, /다른 창/);
});
